mapper.select:
SELECT r.id AS report_id, r.kind AS kind, r.type AS type, r.urgent AS urgent, r.status AS status, r.reporter_id AS reporter_id, rm.nickname AS reporter_nickname, r.target_member_id AS target_id, tm.nickname AS target_nickname, r.basecamp_id AS basecamp_id, r.created_at AS created_at FROM member_report r JOIN member rm ON rm.id = r.reporter_id JOIN member tm ON tm.id = r.target_member_id
r.status = #{status}
AND r.urgent = #{urgent}
ORDER BY r.urgent DESC, (r.type = 'MONEY_REQUEST') DESC, r.created_at ASC, r.id ASC LIMIT #{limit} OFFSET #{offset}
